-- Engelsk niveau-pilot 3/3 på sværhedsskalaen 1-10.000: 166 MC-spørgsmål, niveau 8148-10000 (B2/C1).
-- Del af piloten på 500 engelskopgaver (docs/difficulty-scale-design.md §7, ejerbeslutning B7: CEFR).
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: CEFR-gruppen giver intervallet (A2 3001-5000, B1 5001-7000, B2 7001-8500, C1 8501-10000).
-- Inden for en gruppe er niveauerne fordelt jævnt i forfatterens rækkefølge. Det er et skøn, ikke
-- en måling. target_grade/difficulty_band er afledt baglæns af niveauet (den celle i §4.1, niveauet
-- ligger i), så de gamle visninger og den nuværende udvælgelse har en værdi.
-- Metadata følger mønstret fra de eksisterende engelsk-batches (kategorinøglen k), plus metadata.cefr.
--
-- VIGTIGT: is_active=true. Med det nuværende flow (klassetrinsloft) bliver opgaverne serveret til
-- elever i engelsk, hvis klassetrin >= target_grade, så snart migrationen er anvendt — også før
-- LEVEL_ENGINE slås til. Ejeren afgør ved anvendelsen, om det er ønsket.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'cefr', e->>'cefr', 'domain', 'english'),
  'mc_single', (e->>'b')::int, 'auto', true, 'english', (e->>'g')::int, (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":8148,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The new rules, which were introduced last year, have been widely criticised.' Hvad passer?","o":["Reglerne blev indført i år.","Ingen kan lide de gamle regler.","Mange har kritiseret de nye regler.","Reglerne er blevet fjernet."],"a":"Mange har kritiseret de nye regler.","r":"'Widely criticised' betyder kritiseret af mange."},
{"l":8158,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'She is by no means the only student who struggles with maths.' Hvad betyder det?","o":["Hun er den eneste, der har svært ved matematik.","Hun er god til matematik.","Ingen har svært ved matematik.","Hun er langt fra den eneste, der har svært ved matematik."],"a":"Hun er langt fra den eneste, der har svært ved matematik.","r":"'By no means' betyder på ingen måde."},
{"l":8168,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The village is only accessible by boat during the winter months.' Hvad passer?","o":["Om vinteren kan man kun komme til landsbyen med båd.","Landsbyen er lukket om vinteren.","Man kan aldrig sejle til landsbyen.","Om sommeren kan man kun komme med båd."],"a":"Om vinteren kan man kun komme til landsbyen med båd.","r":"'Only accessible by boat' = kun tilgængelig med båd."},
{"l":8178,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Far from being boring, the lecture turned out to be fascinating.' Hvad passer?","o":["Foredraget var kedeligt.","Foredraget var spændende.","Foredraget blev aflyst.","Foredraget var langt."],"a":"Foredraget var spændende.","r":"'Far from being boring' betyder langt fra kedeligt."},
{"l":8188,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The company's profits fell for the third year in a row.' Hvad passer?","o":["Overskuddet er steget tre år i træk.","Firmaet har tjent penge i tre år.","Overskuddet er faldet tre år i træk.","Firmaet er tre år gammelt."],"a":"Overskuddet er faldet tre år i træk.","r":"'Fell' er datid af fall. 'In a row' betyder i træk."},
{"l":8198,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Little did they know that their lives were about to change forever.' Hvad betyder det?","o":["De vidste godt, at deres liv ville ændre sig.","Deres liv ændrede sig lidt.","De ønskede ikke forandring.","De havde ingen anelse om, at deres liv snart ville ændre sig."],"a":"De havde ingen anelse om, at deres liv snart ville ændre sig.","r":"'Little did they know' er en omvendt ordstilling, der betyder 'de anede ikke'."},
{"l":8208,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The museum attracts more than two million visitors a year, most of whom come from abroad.' Hvad passer?","o":["De fleste besøgende kommer fra udlandet.","De fleste besøgende er lokale.","Museet har to besøgende om året.","Museet ligger i udlandet."],"a":"De fleste besøgende kommer fra udlandet.","r":"'Most of whom come from abroad' = de fleste af dem kommer fra udlandet."},
{"l":8218,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Students are encouraged, though not required, to bring their own laptops.' Hvad passer?","o":["Det er forbudt at medbringe en bærbar.","Det er en god idé at medbringe en bærbar, men ikke et krav.","Man skal medbringe en bærbar.","Skolen udleverer bærbare."],"a":"Det er en god idé at medbringe en bærbar, men ikke et krav.","r":"'Encouraged, though not required' = opfordret til, men ikke påkrævet."},
{"l":8228,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'He was praised for his honesty, which is rare in politics.' Hvad mener skribenten?","o":["Politikere er altid ærlige.","Han blev kritiseret.","Ærlighed er sjælden blandt politikere.","Han er ikke politiker."],"a":"Ærlighed er sjælden blandt politikere.","r":"'Which is rare in politics' = som er sjælden i politik."},
{"l":8238,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The bridge has been closed to traffic pending a safety inspection.' Hvad passer?","o":["Broen er blevet revet ned.","Broen er åben for alle.","Broen er lukket for altid.","Broen er lukket, indtil den er blevet sikkerhedstjekket."],"a":"Broen er lukket, indtil den er blevet sikkerhedstjekket.","r":"'Pending' betyder indtil noget er sket, her: i afventning af et sikkerhedstjek."},
{"l":8248,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Over the past decade, the number of people cycling to work has doubled.' Hvad passer?","o":["Dobbelt så mange cykler til arbejde nu som for ti år siden.","Halvt så mange cykler til arbejde.","Ti procent cykler til arbejde.","Antallet er uændret."],"a":"Dobbelt så mange cykler til arbejde nu som for ti år siden.","r":"'Decade' er ti år, og 'doubled' betyder fordoblet."},
{"l":8259,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'You'd better take a jacket. It's supposed to get cold this evening.' Hvorfor skal man tage en jakke?","o":["Det er koldt nu.","Det forventes at blive koldt i aften.","Det skal regne i morgen.","Jakken er ny."],"a":"Det forventes at blive koldt i aften.","r":"'It's supposed to get cold' = det forventes at blive koldt."},
{"l":8269,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The author's latest novel has received mixed reviews.' Hvad passer?","o":["Alle anmeldere elsker bogen.","Bogen er ikke blevet anmeldt.","Nogle anmeldere kan lide bogen, andre ikke.","Bogen er en blanding af flere bøger."],"a":"Nogle anmeldere kan lide bogen, andre ikke.","r":"'Mixed reviews' betyder blandede anmeldelser."},
{"l":8279,"g":8,"b":4,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Contrary to popular belief, bats are not blind.' Hvad passer?","o":["Flagermus er blinde.","Ingen tror, at flagermus er blinde.","Flagermus ser bedre end mennesker.","Mange tror fejlagtigt, at flagermus er blinde."],"a":"Mange tror fejlagtigt, at flagermus er blinde.","r":"'Contrary to popular belief' = i modsætning til hvad mange tror."},
{"l":8289,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The train was cancelled, so we ended up sharing a taxi with two strangers.' Hvad passer?","o":["De delte en taxa med to fremmede.","De kørte med toget.","De gik hjem.","De tog en taxa alene."],"a":"De delte en taxa med to fremmede.","r":"'Ended up' betyder endte med. 'Strangers' er fremmede."},
{"l":8299,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'It's not that I don't like her; it's just that we have nothing in common.' Hvad passer?","o":["Personen kan ikke lide hende.","Personen kan godt lide hende, men de har ikke noget til fælles.","De har meget til fælles.","De er bedste venner."],"a":"Personen kan godt lide hende, men de har ikke noget til fælles.","r":"Personen forklarer, at problemet ikke er, at han ikke kan lide hende."},
{"l":8309,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Applicants must have at least two years' experience, preferably in sales.' Hvad passer?","o":["Man skal have arbejdet med salg i to år.","Man må ikke have arbejdet med salg.","Erfaring med salg er en fordel, men ikke et krav.","Man skal have mindst fem års erfaring."],"a":"Erfaring med salg er en fordel, men ikke et krav.","r":"'Preferably' betyder helst. Kravet er to års erfaring."},
{"l":8319,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The more expensive model is not necessarily the better one.' Hvad betyder det?","o":["Den dyre model er altid den bedste.","Den billige model er altid dårligst.","Begge modeller er lige dyre.","Den dyre model er ikke altid den bedste."],"a":"Den dyre model er ikke altid den bedste.","r":"'Not necessarily' betyder ikke nødvendigvis."},
{"l":8329,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'He ran so fast that nobody could keep up with him.' Hvad passer?","o":["Ingen kunne følge med ham.","Alle løb hurtigere end ham.","Han var langsom.","Han holdt op med at løbe."],"a":"Ingen kunne følge med ham.","r":"'Keep up with' betyder at følge med."},
{"l":8339,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'She takes her responsibilities seriously, whereas her brother tends to leave everything to the last minute.' Hvad passer?","o":["Søsteren udskyder alt.","Broren udskyder tingene til sidste øjeblik.","Begge er lige ansvarlige.","Broren er meget ansvarlig."],"a":"Broren udskyder tingene til sidste øjeblik.","r":"'Whereas' viser en modsætning. Broren gør alt i sidste øjeblik."},
{"l":8349,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Visitors are kindly requested to refrain from taking photographs.' Hvad betyder det?","o":["Man er velkommen til at fotografere.","Man skal tage mange billeder.","Man bedes lade være med at fotografere.","Man skal spørge om lov til at gå ind."],"a":"Man bedes lade være med at fotografere.","r":"'Refrain from' betyder afholde sig fra."},
{"l":8359,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The results of the survey came as no surprise to the researchers.' Hvad passer?","o":["Forskerne blev meget overraskede.","Undersøgelsen blev aflyst.","Forskerne kender ikke resultaterne.","Forskerne havde forventet resultaterne."],"a":"Forskerne havde forventet resultaterne.","r":"'Came as no surprise' = var ingen overraskelse."},
{"l":8369,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'I'd have called you, only my phone was dead.' Hvorfor ringede personen ikke?","o":["Telefonen var løbet tør for strøm.","Personen ville ikke ringe.","Personen havde ikke nummeret.","Personen ringede faktisk."],"a":"Telefonen var løbet tør for strøm.","r":"'Only' betyder her 'men'. 'My phone was dead' = telefonen var død."},
{"l":8379,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'The flat is conveniently located within walking distance of the station.' Hvad passer?","o":["Lejligheden ligger langt fra stationen.","Man kan gå fra lejligheden til stationen.","Lejligheden ligger på stationen.","Man skal tage bussen til stationen."],"a":"Man kan gå fra lejligheden til stationen.","r":"'Within walking distance' = inden for gåafstand."},
{"l":8389,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","q":"Læs: 'Ben was the last person I expected to see at a yoga class.' Hvad mener personen?","o":["Ben kommer altid til yoga.","Ben var den sidste, der kom.","Det var meget overraskende at se Ben til yoga.","Personen så ikke Ben."],"a":"Det var meget overraskende at se Ben til yoga.","r":"'The last person I expected' = den, man mindst havde ventet."},
{"l":8399,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","q":"Hvilket ord passer: 'Supposing you ___ the lottery, what would you do?'","o":["win","had won","will win","won"],"a":"won","r":"'Supposing' fungerer som 'if' i anden konditional: supposing you won."},
