{"l":8420,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","q":"Hvilket ord passer: 'She apologised ___ late.'","o":["to be","for being","for be","being"],"a":"for being","r":"Man siger 'apologise for' + -ing."},
