{"l":8450,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'drawback'?","o":["ulempe","tilbagetog","tegning","rabat"],"a":"ulempe","r":"'Drawback' betyder en ulempe."},
